class ValueRefStore<T> extends _BaseValueStore<T> {
  static const _refs = '__refs';

  ValueRefStore([super.store]);

  void _subtractRef(Map refs, Object? value, int count) {
    final remaining = refs[value] - count;
    if (remaining == 0) {
      refs.remove(value);
    } else {
      refs[value] = remaining;
    }
  }

  T? _write(Map node, String path, int start, T value) {
    final end = _nextStoreDelimiter(path, start);

    T? prevValue;
    if (end < 0) {
      final values = node[_BaseValueStore._values] ??= <String, T>{};
      final segment = path.substring(start);
      prevValue = values[segment];
      values[segment] = value;
    } else {
      final Map child = node[path.substring(start, end)] ??= {};
      prevValue =
          _write(child, path, end + _BaseValueStore.delimiter.length, value);
    }

    if (prevValue == value) {
      return value;
    }

    final refs = node[_refs] ??= {};
    refs[value] = (refs[value] ?? 0) + 1;

    if (prevValue != null) {
      _subtractRef(refs, prevValue, 1);
    }

    return prevValue;
  }

  Map? _delete(
    Map node,
    String path,
    int start,
    bool recursive,
  ) {
    final end = _nextStoreDelimiter(path, start);
    final segment = path.substring(start, end < 0 ? path.length : end);
    final Map? child = node[segment];

    T? childValue;
    Map? removedRefs;

    if (end >= 0) {
      if (child == null) {
        return null;
      }

      removedRefs = _delete(
          child, path, end + _BaseValueStore.delimiter.length, recursive);
      if (child.isEmpty) {
        node.remove(segment);
      }
    } else {
      final Map? values = node[_BaseValueStore._values];
      if (values != null) {
        childValue = values[segment];
        if (childValue != null) {
          if (values.length == 1) {
            node.remove(_BaseValueStore._values);
          } else {
            values.remove(segment);
          }
        }
      }

      if (recursive && child != null) {
        removedRefs = child[_refs]!;

        if (childValue != null) {
          removedRefs![childValue] = (removedRefs[childValue] ?? 0) + 1;
        }

        node.remove(segment);
      } else if (childValue != null) {
        removedRefs = {childValue: 1};
      }
    }

    if (removedRefs != null) {
      final Map nodeRefs = node[_refs];

      for (final entry in removedRefs.entries) {
        _subtractRef(nodeRefs, entry.key, entry.value);
      }
      if (nodeRefs.isEmpty) node.remove(_refs);
    }

    return removedRefs;
  }

  /// Returns a map of all values that exist under the given path to their ref count.
  Map<T, int>? getRefs([String path = '']) {
    if (_store.isEmpty) {
      return null;
    }

    final Map? node = path.isEmpty ? _store : _getNode(path);
    if (node == null) {
      return null;
    }

    final refs = node[_refs];
    if (refs is Map<T, int>?) {
      return refs;
    }

    // If the store was hydrated, then the refs may have been instantiated as a
    // `Map<String, dynamic>` in which case it must be converted to a Map<String, int>.
    return node[_refs] = Map<T, int>.from(refs);
  }

  @override

  /// A [ValueRefStore] overrides the default [ValueStore.extractValues] behavior
  /// since the values under a given path are pre-computed by the ref store.
  Set<T> extractValues([String path = '']) {
    return getRefs(path)?.keys.toSet() ?? {};
  }

  @override
  T write(String path, T value) {
    _write(_store, path, 0, value);
    return value;
  }

  @override
  delete(
    String path, {
    bool recursive = true,
  }) {
    if (path.isEmpty) {
      _store = {};
      return;
    }

    if (_store.isEmpty) return;

    _delete(_store, path, 0, recursive);
  }
}

