import 'store.dart';
import 'profile_support.dart';

/// Store-only workloads shared by the Dart isolation runner and Flutter hosts.
/// Paths are prepared once; mutation setup and result checks stay outside timing.
void profileStoreCore() {
  final results = ProfileResults();
  final filter = profileSetting('PROFILE_FILTER');
  final selected = filter == null ? null : RegExp(filter);
  const n = 20000;
  const repeats = 100000;
  const total = n * (n - 1) ~/ 2;
  final shallowPaths = [for (var i = 0; i < n; i++) 'items__$i'];
  final deepPaths = [
    for (var i = 0; i < n; i++) 'orgs__o__teams__t__accounts__a__items__$i'
  ];

  void measure<R>(String name, R Function() action, bool Function(R) validate,
      {void Function()? prepare, int operations = 1}) {
    if (selected != null && !selected.hasMatch(name)) return;
    final samples = <int>[];
    for (final record in samplePhases()) {
      prepare?.call();
      final watch = Stopwatch()..start();
      final result = action();
      watch.stop();
      check(validate(result), 'store_core/$name');
      if (record) samples.add(watch.elapsedMicroseconds);
    }
    results.add(name, samples, {'operations': operations});
  }

  final empty = ValueStore<int>();
  measure('empty/get', () {
    var missing = 0;
    for (var i = 0; i < repeats; i++) {
      if (empty.get('missing__child') == null) missing++;
    }
    return missing;
  }, (missing) => missing == repeats, operations: repeats);

  for (final (shape, paths) in [
    ('shallow', shallowPaths),
    ('deep', deepPaths)
  ]) {
    final store = ValueStore<int>();
    void seed() {
      store.clear();
      for (var i = 0; i < n; i++) {
        store.write(paths[i], i);
      }
    }

    seed();
    final prefix = paths.first.substring(0, paths.first.lastIndexOf('__'));
    measure('$shape/get', () {
      var sum = 0;
      for (final path in paths) {
        sum += store.get(path)!;
      }
      return sum;
    }, (sum) => sum == total, operations: n);
    for (final (kind, path) in [
      ('value', paths.last),
      ('node', prefix),
      ('early_miss', 'missing__${prefix}__0'),
      ('late_miss', '${prefix}__missing'),
    ]) {
      if (kind.endsWith('miss')) {
        measure('$shape/get_$kind', () {
          var missing = 0;
          for (var i = 0; i < repeats; i++) {
            if (store.get(path) == null) missing++;
          }
          return missing;
        }, (missing) => missing == repeats, operations: repeats);
      }
      measure('$shape/has_path_$kind', () {
        var hits = 0;
        for (var i = 0; i < repeats; i++) {
          if (store.hasPath(path)) hits++;
        }
        return hits;
      }, (hits) => hits == (kind.endsWith('miss') ? 0 : repeats),
          operations: repeats);
    }
    measure('$shape/child_values', () {
      var count = 0;
      for (var i = 0; i < repeats; i++) {
        count += store.getChildValues(prefix)!.length;
      }
      return count;
    }, (count) => count == repeats * n, operations: repeats);
    measure('$shape/nearest_leaf', () {
      var sum = 0;
      for (final path in paths) {
        sum += store.getNearest(path)!.$2;
      }
      return sum;
    }, (sum) => sum == total, operations: n);
    measure('$shape/extract_single', () {
      var sum = 0;
      for (final path in paths) {
        sum += store.extractValues(path).single;
      }
      return sum;
    }, (sum) => sum == total, operations: n);
    measure('$shape/write_new', () {
      for (var i = 0; i < n; i++) {
        store.write(paths[i], i);
      }
      return store;
    },
        (store) =>
            store.extractValues().length == n && store.get(paths.last) == n - 1,
        prepare: store.clear,
        operations: n);
    measure('$shape/overwrite', () {
      for (var i = 0; i < n; i++) {
        store.write(paths[i], i + 1);
      }
      return store;
    }, (store) => store.get(paths.first) == 1 && store.get(paths.last) == n,
        prepare: seed, operations: n);
    measure('$shape/delete_leaves', () {
      for (final path in paths) {
        store.delete(path);
      }
      return store.isEmpty;
    }, (empty) => empty, prepare: seed, operations: n);
  }

  final widePaths = [for (var i = 0; i < n; i++) 'accounts__${i}__items__0'];
  final wide = ValueStore<int>();
  void seedWide() {
    for (var i = 0; i < n; i++) {
      wide.write(widePaths[i], i);
    }
  }

  measure('wide/write_new', () {
    seedWide();
    return wide;
  }, (store) => store.extractValues().length == n,
      prepare: wide.clear, operations: n);
  measure('wide/delete_leaves', () {
    for (final path in widePaths) {
      wide.delete(path);
    }
    return wide.isEmpty;
  }, (empty) => empty, prepare: seedWide, operations: n);

  final refs = ValueRefStore<int>();
  void seedRefs() {
    for (var i = 0; i < n; i++) {
      refs.write(deepPaths[i], i % 64);
    }
  }

  measure('refs/write_shared', () {
    seedRefs();
    return refs;
  },
      (store) =>
          store.getRefs()!.length == 64 &&
          store.getRefs()!.values.fold(0, (sum, count) => sum + count) == n,
      prepare: refs.clear,
      operations: n);
  measure('refs/delete_shared', () {
    for (final path in deepPaths) {
      refs.delete(path);
    }
    return refs.isEmpty;
  }, (empty) => empty, prepare: seedRefs, operations: n);
  measure('refs/overwrite_shared', () {
    for (var i = 0; i < n; i++) {
      refs.write(deepPaths[i], (i + 1) % 64);
    }
    return refs;
  },
      (store) =>
          store.get(deepPaths.first) == 1 &&
          store.getRefs()!.length == 64 &&
          store.getRefs()!.values.fold(0, (sum, count) => sum + count) == n,
      prepare: seedRefs,
      operations: n);
  measure('refs/delete_subtree', () {
    refs.delete('orgs__o__teams__t__accounts__a__items');
    return refs.isEmpty;
  }, (empty) => empty, prepare: seedRefs);

  // IDs can be much longer than collection names, and Dart supports both
  // one-byte and two-byte strings. Keep delimiter optimizations honest across
  // those shapes, including non-overlapping runs of underscores.
  const pathCount = 10000;
  const pathTotal = pathCount * (pathCount - 1) ~/ 2;
  final longSegment = 'x' * 128;
  for (final (shape, prefix, idPrefix) in [
    (
      'uuid',
      'accounts__17cf805b-9f50-4fcf-b33a-2589a4c09fca__items',
      '117aea65-c56c-4950-bf57-'
    ),
    ('long_segments', '${longSegment}__${longSegment}__items', longSegment),
    ('unicode', '組織💙__北區__帳戶__項目', '文書🎈'),
    ('underscores', 'org_units__alpha_beta___branch____items', '_entry_'),
  ]) {
    final paths = [
      for (var i = 0; i < pathCount; i++) '${prefix}__$idPrefix$i'
    ];
    final store = ValueStore<int>();
    void seed() {
      for (var i = 0; i < pathCount; i++) {
        store.write(paths[i], i);
      }
    }

    seed();
    measure('path_shape/$shape/get', () {
      var sum = 0;
      for (final path in paths) {
        sum += store.get(path)!;
      }
      return sum;
    }, (sum) => sum == pathTotal, operations: pathCount);
    measure('path_shape/$shape/write_new', () {
      seed();
      return store;
    }, (store) => store.extractValues().length == pathCount,
        prepare: store.clear, operations: pathCount);
  }

  final ancestors = ValueStore<int>();
  final chain = [for (var i = 0; i < 12; i++) 'level$i'];
  for (var i = 0; i < chain.length; i++) {
    ancestors.write(chain.take(i + 1).join('__'), i);
  }
  ancestors.write('', -1);
  final full = chain.join('__');
  for (final (name, path, expected) in [
    ('leaf', full, 11),
    ('fallback', '${full}__missing__more', 11),
    ('root', 'missing__more', -1),
  ]) {
    measure('ancestors/nearest_$name', () {
      var sum = 0;
      for (var i = 0; i < n; i++) {
        sum += ancestors.getNearest(path)!.$2;
      }
      return sum;
    }, (sum) => sum == n * expected, operations: n);
  }
  final matchedAncestor = chain.take(4).join('__');
  measure('ancestors/match', () {
    var count = 0;
    for (var i = 0; i < n; i++) {
      if (ancestors.getNearestMatch(full, 3) == matchedAncestor) count++;
    }
    return count;
  }, (count) => count == n, operations: n);
  measure('ancestors/extract', () {
    var count = 0;
    for (var i = 0; i < n; i++) {
      count += ancestors.extractParentPath(full).length;
    }
    return count;
  }, (count) => count == n * 13, operations: n);

  for (final shape in [
    'flat',
    'buckets',
    'singletons',
    'deep_nodes',
    'duplicates'
  ]) {
    final store = ValueStore<int>();
    final count = shape == 'flat' || shape == 'duplicates' ? 100000 : n;
    for (var i = 0; i < count; i++) {
      final path = switch (shape) {
        'flat' || 'duplicates' => 'items__$i',
        'buckets' => 'accounts__${i ~/ 1000}__items__${i % 1000}',
        'singletons' => 'accounts__${i}__value',
        _ => 'accounts__${i}__a__b__c__d__e__value',
      };
      store.write(path, shape == 'duplicates' ? i % 100 : i);
    }
    final distinct = shape == 'duplicates' ? 100 : count;
    final expected = [for (var i = 0; i < distinct; i++) i];
    bool ordered(Iterable<int> actual) {
      final iterator = actual.iterator;
      for (final value in expected) {
        if (!iterator.moveNext() || iterator.current != value) return false;
      }
      return !iterator.moveNext();
    }

    measure('extract_values/$shape', store.extractValues, ordered,
        operations: count);
    measure(
        'extract_map/$shape',
        store.extract,
        (map) =>
            map.length == count &&
            map.values.fold(0, (a, b) => a + b) ==
                (shape == 'duplicates'
                    ? count ~/ 100 * 4950
                    : count * (count - 1) ~/ 2),
        operations: count);
  }
  check(results.rows.isNotEmpty, 'No store operations matched $filter');
  results.save();
}

frozen_harness.profile_support.dart:
import 'dart:convert';
import 'dart:io';

const kReleaseMode = bool.fromEnvironment('CORE_AOT');
const kProfileMode = false;

// Environment overrides make one compiled desktop binary reusable. Dart defines
// provide the same settings for Flutter runs on physical mobile devices.
const _defines = {
  'PROFILE_WARMUPS': String.fromEnvironment('PROFILE_WARMUPS'),
  'PROFILE_WARMUP_MS': String.fromEnvironment('PROFILE_WARMUP_MS'),
  'PROFILE_TRIALS': String.fromEnvironment('PROFILE_TRIALS'),
  'PROFILE_ORDER': String.fromEnvironment('PROFILE_ORDER'),
  'PROFILE_CASE': String.fromEnvironment('PROFILE_CASE'),
  'PROFILE_SUITE': String.fromEnvironment('PROFILE_SUITE'),
  'PROFILE_VARIANT': String.fromEnvironment('PROFILE_VARIANT'),
  'PROFILE_EXPECT_MODE': String.fromEnvironment('PROFILE_EXPECT_MODE'),
  'PROFILE_START_DELAY_MS': String.fromEnvironment('PROFILE_START_DELAY_MS'),
  'PROFILE_EXIT': String.fromEnvironment('PROFILE_EXIT'),
};

String? profileSetting(String name) {
  final value = Platform.environment[name] ?? _defines[name];
  return value == null || value.isEmpty ? null : value;
}

final warmups = int.parse(profileSetting('PROFILE_WARMUPS') ?? '5');
final warmupMillis = int.parse(profileSetting('PROFILE_WARMUP_MS') ?? '250');
final trials = int.parse(profileSetting('PROFILE_TRIALS') ?? '15');
String get profileMode =>
    kReleaseMode ? 'aot' : (kProfileMode ? 'profile' : 'jit');

void check(bool condition, String message) {
  // Dart assert is disabled in release; benchmark validation must remain active.
  if (!condition) throw StateError(message);
}

Iterable<bool> samplePhases() sync* {
  check(warmups >= 1 && trials >= 1 && warmupMillis >= 0, 'Invalid repetition');
  final elapsed = Stopwatch()..start();
  var count = 0;
  while (count < warmups || elapsed.elapsedMilliseconds < warmupMillis) {
    yield false;
    count++;
  }
  for (var i = 0; i < trials; i++) {
    yield true;
  }
}

class ProfileResults {
  static final completed = <Map<String, Object?>>[];
  static bool nativeHost = false;
  final rows = <Map<String, Object>>[];

  void measure(String name, int Function() action,
      {required int expected, int operations = 1, void Function()? prepare}) {
    final samples = <int>[];
    int? firstSample;
    for (final recordSample in samplePhases()) {
      prepare?.call();
      final watch = Stopwatch()..start();
      final actual = action();
      watch.stop();
      check(actual == expected, '$name: expected $expected, got $actual');
      firstSample ??= watch.elapsedMicroseconds;
      if (recordSample) samples.add(watch.elapsedMicroseconds);
    }
    add(name, samples,
        {'operations': operations, 'first_sample_us': firstSample!});
  }

  void add(String name, List<int> samples,
      [Map<String, Object> details = const {}]) {
    final ordered = List.of(samples)..sort();
    final middle = ordered.length ~/ 2;
    final median = ordered.length.isOdd
        ? ordered[middle].toDouble()
        : (ordered[middle - 1] + ordered[middle]) / 2;
    rows.add(
        {'name': name, ...details, 'median_us': median, 'samples_us': samples});
  }

  void save() {
    final data = {
      'schema': 2,
      'dart': Platform.version,
      'os': Platform.operatingSystem,
      'mode': profileMode,
      'host': nativeHost ? 'flutter_app' : 'flutter_test',
      'variant': profileSetting('PROFILE_VARIANT') ?? 'workspace',
      'suite': profileSetting('PROFILE_SUITE'),
      'warmups': warmups,
      'minimum_warmup_ms': warmupMillis,
      'trials': trials,
      'rows': rows,
    };
    completed.add(data);
    if (nativeHost) return;
    final json = const JsonEncoder.withIndent('  ').convert(data);
    final output = Platform.environment['PROFILE_OUTPUT'];
    if (output != null) File(output).writeAsStringSync(json);
    // ignore: avoid_print
    print(json);
  }
}

lib/store/base_value_store.dart.source:
part of '../loon.dart';

abstract class _BaseValueStore<T> {
  Map _store = {};

  static const _values = '__values';
  static const delimiter = '__';
  static const root = '';

  _BaseValueStore([Map? store]) {
    if (store != null) {
      _store = store;
    }
  }

  /// Returns the node that owns the final segment of [path] together with that segment, or null
  /// if the parent node is missing. `parent[_values][segment]` is the path's value and
  /// `parent[segment]` its child node.
  ///
  /// Segments are parsed as they are visited rather than split up front, so a lookup allocates
  /// only the segments it reaches and stops at the first missing node.
  @pragma('vm:prefer-inline')
  (Map, String)? _getParent(String path) {
    if (_store.isEmpty) {
      return null;
    }

    Map node = _store;
    var start = 0;
    while (true) {
      final end = _nextStoreDelimiter(path, start);
      if (end < 0) {
        return (node, path.substring(start));
      }

      final Map? child = node[path.substring(start, end)];
      if (child == null) {
        return null;
      }
      node = child;
      start = end + delimiter.length;
    }
  }

  Map? _getNode(String path) {
    if (_getParent(path) case (final parent, final segment)) {
      return parent[segment];
    }
    return null;
  }

  (String, T)? _getNearest(
    Map? node,
    String path,
    int start,
    T? value,
  ) {
    if (node == null) {
      return null;
    }

    final end = _nextStoreDelimiter(path, start);
    final segment = path.substring(start, end < 0 ? path.length : end);

    if (end >= 0) {
      final result =
          _getNearest(node[segment], path, end + delimiter.length, value);
      if (result != null) {
        return result;
      }
    }

    final nodeValue = node[_values]?[segment];
    if (nodeValue != null && (value == null || nodeValue == value)) {
      return (end < 0 ? path : path.substring(0, end), nodeValue);
    }

    if (start > 0) {
      return null;
    }

    if (_store[_values]?[root] case T rootValue) {
      return (root, rootValue);
    }

    return null;
  }

  Map<String, T> _extractParentPath(
    Map node,
    String path,
    int start,
    Map<String, T> values,
  ) {
    while (true) {
      final end = _nextStoreDelimiter(path, start);
      final segment = path.substring(start, end < 0 ? path.length : end);
      final value = node[_values]?[segment];
      if (value != null) {
        values[end < 0 ? path : path.substring(0, end)] = value;
      }
      if (end < 0) break;
      final Map? child = node[segment];
      if (child == null) break;
      node = child;
      start = end + delimiter.length;
    }
    final rootValue = _store[_values]?[root];
    if (rootValue != null) values[ValueStore.root] = rootValue;
    return values;
  }

  Map<String, T> _extract(
    Map? node,
    Map<String, T> values,
    String path,
  ) {
    if (node == null) {
      return values;
    }

    final Map? localValues = node[_values];
    if (localValues != null) {
      localValues.forEach((key, value) {
        values[path.isEmpty ? key : '$path$delimiter$key'] = value;
      });
      if (node.length == 1) return values;
    }

    node.forEach((key, child) {
      if (key != _values) {
        _extract(child, values, path.isEmpty ? key : '$path$delimiter$key');
      }
    });

    return values;
  }

  Set<T> _extractValues(Map? node, Set<T> values) {
    if (node == null) {
      return values;
    }

    final Map<String, T>? nodeValues = node[_values];

    if (nodeValues != null) {
      values.addAll(nodeValues.values);
      if (node.length == 1) return values;
    }

    node.forEach((key, child) {
      if (key != _values) _extractValues(child, values);
    });

    return values;
  }

  T? get(String path) {
    if (_getParent(path) case (final parent, final segment)) {
      return parent[_values]?[segment];
    }
    return null;
  }

  /// Returns a map of all values that are immediate children of the given path.
  Map<String, T>? getChildValues(String path) {
    return _getNode(path)?[_values];
  }

  /// Returns the nearest path/value pair that has a value along the given path, beginning at the full path
  /// and then attempting to find a non-null value at any parent node moving up the tree.
  (String, T)? getNearest(String path) {
    return _getNearest(_store, path, 0, null);
  }

  /// Returns the nearest path that has a matching value along the given path.
  String? getNearestMatch(String path, T value) {
    return _getNearest(_store, path, 0, value)?.$1;
  }

  bool hasValue(String path) {
    return get(path) != null;
  }

  /// Returns whether the path exists in the store, either as a value or path to another descendant value.
  bool hasPath(String path) {
    if (path.isEmpty) return true;
    if (_getParent(path) case (final parent, final segment)) {
      return parent[_values]?[segment] != null || parent[segment] != null;
    }
    return false;
  }

  T write(String path, T value);
  void delete(String path, {bool recursive = true});

  /// Extracts all values under the given path into a map of flattened paths to values.
  Map<String, T> extract([String path = '']) {
    if (path.isEmpty) {
      return _extract(_store, {}, path);
    }

    final Map<String, T> values = {};

    if (_getParent(path) case (final parent, final segment)) {
      if (parent[_values]?.containsKey(segment) ?? false) {
        values[path] = parent[_values][segment];
      }

      return _extract(parent[segment], values, path);
    }

    return values;
  }

  /// Extracts all values at parent paths of the given path into a set of flat key-value pairs of paths to values.
  /// For example, if the path is users__1__friends__1 and both users__1 and users__1__friends__1
  /// exist as distinct values in the store, then it returns both values.
  Map<String, T> extractParentPath(String path) {
    return _extractParentPath(_store, path, 0, {});
  }

  /// Returns a set of the unique values that exist in the store under the given path.
  Set<T> extractValues([String path = '']) {
    if (path.isEmpty) {
      return _extractValues(_store, {});
    }

    final Set<T> values = {};

    if (_getParent(path) case (final parent, final segment)) {
      if (parent[_values]?.containsKey(segment) ?? false) {
        values.add(parent[_values][segment]);
      }

      return _extractValues(parent[segment], values);
    }

    return values;
  }

  bool get isEmpty {
    return _store.isEmpty;
  }

  /// Returns whether the store has any child values under the given path.
  bool hasChildValues(String path) {
    return getChildValues(path)?.isNotEmpty ?? false;
  }

  void clear() {
    _store = {};
  }

  Map inspect() {
    return _store;
  }

  /// While unreferenced in the codebase, toJson is implemented so that the store can be serialized
  /// using the default behavior of [jsonEncode] which is to attempt to call [toJson] on complex objects.
  Map toJson() {
    return inspect();
  }
}

