part of '../loon.dart';

/// Finds the next `__` separator. Specializing the fixed two-character delimiter
/// avoids the general substring search on every segment of a store path.
/// Callers advance past both characters to preserve non-overlapping matches.
@pragma('vm:prefer-inline')
int _nextStoreDelimiter(String path, int start) {
  const underscore = 0x5f;
  for (var i = start; i < path.length - 1; i++) {
    if (path.codeUnitAt(i) == underscore &&
        path.codeUnitAt(i + 1) == underscore) {
      return i;
    }
  }
  return -1;
}

/// Returns the index at which the final segment of [path] begins. Delimiters are matched
/// left to right without overlapping, as [String.split] does, so `a___b` ends in `_b`.
int _lastSegmentStart(String path) {
  const delimiter = _BaseValueStore.delimiter;
  var start = 0;
  while (true) {
    final end = _nextStoreDelimiter(path, start);
    if (end < 0) return start;
    start = end + delimiter.length;
  }
}

/// Splits [path] into its parent path and final segment, materializing only those two strings.
(String, String) _splitReferencePath(String path) {
  final start = _lastSegmentStart(path);
  return start == 0
      ? ('', path)
      : (
          path.substring(0, start - _BaseValueStore.delimiter.length),
          path.substring(start),
        );
}

lib/dependency_manager.dart.source:
part of 'loon.dart';

/// Keeps the dependent handle available when its dependency entries are deleted.
class _DependencyEntry {
  final Document doc;
  final Set<Document> dependencies;

  _DependencyEntry(this.doc, this.dependencies);

  Json toJson() => {
        'doc': doc.path,
        'dependencies': [
          for (final dependency in dependencies) dependency.path
        ],
      };
}

class DependencyManager {
  /// The index of dependencies of a document by path.
  final _dependencies = ValueStore<_DependencyEntry>();

  /// The reverse index of dependents of a document by path.
  final _dependents = ValueStore<Set<Document>>();

  void _addDependent(Document dependency, Document dependent) {
    final dependents = _dependents.get(dependency.path) ??
        _dependents.write(dependency.path, {});
    dependents.add(dependent);
  }

  Set<Document>? _removeDependent(
    Document dependency,
    Document dependent, {
    Set<Document>? dependents,
  }) {
    dependents ??= _dependents.get(dependency.path);
    if (dependents == null) return null;

    dependents.remove(dependent);
    if (dependents.isEmpty) {
      _dependents.delete(dependency.path, recursive: false);
      return null;
    }
    return dependents;
  }

  /// Updates the dependencies/dependents store for the given [DocumentSnapshot]
  /// with the document's recalculated dependencies.
  void updateDependencies<T>(DocumentSnapshot<T> snap) {
    final doc = snap.doc;
    final dependenciesBuilder = doc.dependenciesBuilder;

    if (dependenciesBuilder == null) {
      return;
    }

    // Keep the previous dependencies independent of a mutable set owned by the builder.
    final deps = dependenciesBuilder.call(snap)?.toSet();
    final prevDeps = _dependencies.get(doc.path)?.dependencies;

    if (setEquals(deps, prevDeps)) {
      return;
    }

    if (deps != null && prevDeps != null) {
      for (final dep in deps) {
        if (!prevDeps.contains(dep)) {
          _addDependent(dep, doc);
        }
      }
      for (final dep in prevDeps) {
        if (!deps.contains(dep)) {
          _removeDependent(dep, doc);
        }
      }

      if (deps.isEmpty) {
        // Only the document's own dependencies are removed; the documents of its
        // subcollections keep theirs.
        _dependencies.delete(doc.path, recursive: false);
      } else {
        _dependencies.write(doc.path, _DependencyEntry(doc, deps));
      }
    } else if (deps != null) {
      for (final dep in deps) {
        _addDependent(dep, doc);
      }

      _dependencies.write(doc.path, _DependencyEntry(doc, deps));
    } else if (prevDeps != null) {
      for (final dep in prevDeps) {
        _removeDependent(dep, doc);
      }

      _dependencies.delete(doc.path, recursive: false);
    }
  }

  /// Returns all dependencies of the given document.
  Set<Document>? getDependencies(Document doc) {
    return _dependencies.get(doc.path)?.dependencies;
  }

  /// Returns all dependents under the given store reference.
  Set<Document>? getDependents(
    StoreReference ref, {
    bool recursive = false,
  }) {
    return recursive
        ? _dependents.extractValues(ref.path).flatten()
        : _dependents.get(ref.path);
  }

  /// Deleting a store ref performs two operations:
  ///
  /// 1. It deletes all dependency entries under the given path.
  /// 2. It removes the deleted documents from their dependencies' reverse indexes.
  ///
  /// Surviving documents that depend on the deleted path keep their memberships,
  /// so they can react to both its deletion and later recreation.
  void _deleteRef(StoreReference ref) {
    final StoreReference(:path) = ref;

    final entries = _dependencies.extractValues(path);
    _dependencies.delete(path);

    // Reuse a shared dependency's set only within this removal operation.
    String? previousPath;
    Set<Document>? previousDependents;
    for (final entry in entries) {
      for (final dependency in entry.dependencies) {
        final path = dependency.path;
        previousDependents = _removeDependent(dependency, entry.doc,
            dependents: path == previousPath ? previousDependents : null);
        previousPath = path;
      }
    }
  }

  void deleteDocument(Document doc) {
    _deleteRef(doc);
  }

  void deleteCollection(Collection collection) {
    _deleteRef(collection);
  }

  /// Clears all dependencies and dependents of documents.
  void clear() {
    _dependencies.clear();
    _dependents.clear();
  }

  Map inspect() {
    return {
      "dependencyStore": _dependencies.inspect(),
      "dependentsStore": _dependents.inspect(),
    };
  }
}

lib/broadcast_manager.dart.source:
part of './loon.dart';

enum BroadcastEvents {
  /// The document has been modified.
  modified,

  /// The document has been added.
  added,

  /// The document has been removed.
  removed,

  /// The document has been touched: its observers re-read it and the queries on its collection
  /// re-evaluate it, either manually through [Document.rebroadcast] or because a document it
  /// depends on was written or deleted.
  touched,

  /// The document has been hydrated from persisted storage.
  hydrated,
}

/// The broadcast manager handles all logic related to the active broadcast observers.
/// Its functions include:
/// 1. Maintaining the set of active broadcast observers.
/// 2. Maintaining the event store of changes to deliver to observers on broadcast.
/// 3. Scheduling and firing the broadcast to observers.
/// 4. Maintaining the store of cached broadcast observer values.
class BroadcastManager {
  /// The store of documents/collections events scheduled for broadcast.
  final eventStore = ValueStore<BroadcastEvents>();

  /// The store of broadcast observer values.
  final observerValueStore = ValueStore();

  /// The set of broadcast observers that should be notified on broadcast. Observers are tracked
  /// by identity, since observable documents compare equal to the documents they observe.
  final Set<BroadcastObserver> _observers = LinkedHashSet.identity();

  /// Non-null while a broadcast is scheduled or currently draining.
  Timer? _broadcastTimer;

  bool get _pendingBroadcast => _broadcastTimer != null;

  void _cancelBroadcast() {
    _broadcastTimer?.cancel();
    _broadcastTimer = null;
  }

  void _scheduleBroadcast() {
    if (!_pendingBroadcast) {
      // The broadcast is run async so that multiple broadcast events can be batched
      // together into one update across all changes that occur in the current task of the event loop.
      _broadcastTimer = Timer(Duration.zero, _broadcast);
    }
  }

  void _broadcast() {
    for (final observer in _observers.toList()) {
      observer._onBroadcast();
    }

    eventStore.clear();
    _broadcastTimer = null;
  }

  void _broadcastDependents(
    StoreReference ref, {
    bool recursive = false,
  }) {
    final dependents = Loon._instance.dependencyManager
        .getDependents(ref, recursive: recursive);
    if (dependents == null || dependents.isEmpty) return;
    _queueDependentEvents(dependents);
  }

  void _queueDependentEvents(Set<Document> dependents) {
    final manager = Loon._instance.dependencyManager;

    // This synchronous walk only adds events and reads the reverse index. Keep
    // at most one collection map from each store, only until the walk returns.
    String? eventParent;
    Map<String, BroadcastEvents>? events;
    String? reverseParent;
    Map<String, Set<Document>>? reverse;

    void visit(Set<Document> dependents) {
      for (final doc in dependents) {
        // Unusual constructor inputs can split differently from parent/id.
        final useBucket = doc.id.isNotEmpty &&
            !doc.id.contains('__') &&
            !doc.parent.endsWith('_');
        if (useBucket && eventParent != doc.parent) {
          eventParent = doc.parent;
          events = eventStore.getChildValues(doc.parent);
        }
        final pending =
            useBucket ? (events?[doc.id]) : eventStore.get(doc.path);
        if (pending != null) continue;

        observerValueStore.delete(doc.path, recursive: false);
        observerValueStore.delete(doc.parent, recursive: false);
        if (useBucket && events != null) {
          events![doc.id] = BroadcastEvents.touched;
        } else {
          eventStore.write(doc.path, BroadcastEvents.touched);
          if (useBucket) {
            events = eventStore.getChildValues(doc.parent);
          } else {
            // This write may have created a bucket previously cached as absent.
            eventParent = null;
          }
        }

        Set<Document>? next;
        if (useBucket) {
          if (reverseParent != doc.parent) {
            reverseParent = doc.parent;
            reverse = manager._dependents.getChildValues(doc.parent);
          }
          next = reverse?[doc.id];
        } else {
          next = manager.getDependents(doc);
        }
        if (next != null) visit(next);
      }
    }

    visit(dependents);
  }

  void _deleteRef(StoreReference ref) {
    final StoreReference(:path) = ref;

    // Replace all pending events for the deleted path and its subtree with a
    // single removed event at the deleted path.
    eventStore.delete(path);
    eventStore.write(path, BroadcastEvents.removed);

    // Deleting a path invalidates all cached values under that path in the observer value store.
    observerValueStore.delete(path);

    // Deleting a reference schedules all dependents under that path for broadcast.
    _broadcastDependents(ref, recursive: true);

    _scheduleBroadcast();
  }

  void writeDocument(Document doc, BroadcastEvents event) {
    final path = doc.path;

    // All cached observer values for the document and its collection are invalidated whenever
    // the document is written or touched.
    observerValueStore.delete(path, recursive: false);
    observerValueStore.delete(doc.parent, recursive: false);

    final pendingEvent = eventStore.get(path);
    // Ignore writing a duplicate event or overwriting a pending mutative event type with a touched event.
    if (pendingEvent == null ||
        (event != pendingEvent && event != BroadcastEvents.touched)) {
      eventStore.write(path, event);
    }

    _broadcastDependents(doc);
    _scheduleBroadcast();
  }

  void deleteCollection(Collection collection) {
    _deleteRef(collection);
  }

  void deleteDocument(Document doc) {
    _deleteRef(doc);

    // All cached observer values for the document's collection are also invalidated after
    // the document is deleted.
    observerValueStore.delete(doc.parent, recursive: false);
  }

  void clear({bool broadcast = true}) {
    _cancelBroadcast();
    eventStore.clear();
    observerValueStore.clear();

    if (broadcast) {
      for (final observer in _observers) {
        eventStore.write(observer.path, BroadcastEvents.removed);
      }

      _scheduleBroadcast();
    }
  }

  void addObserver<T, S>(BroadcastObserver<T, S> observer, T initialValue) {
    _observers.add(observer);

    observerValueStore.write(observer._observerId, initialValue);
  }

  void removeObserver(BroadcastObserver observer) {
    _observers.remove(observer);

    observerValueStore.delete(observer._observerId);
  }

  void unsubscribe() {
    _cancelBroadcast();
    eventStore.clear();
    for (final observer in _observers.toList()) {
      observer.dispose();
    }
    _observers.clear();
    observerValueStore.clear();
  }

  Map inspect() {
    return {
      "events": eventStore.inspect(),
      "observerValues": observerValueStore.inspect(),
    };
  }
}

