lib/store/base_value_store.dart.source:
part of '../loon.dart';

abstract class _BaseValueStore<T> {
  Map _store = {};

  static const _values = '__values';
  static const delimiter = '__';
  static const root = '';

  _BaseValueStore([Map? store]) {
    if (store != null) {
      _store = store;
    }
  }

  /// Returns the node that owns the final segment of [path] together with that segment, or null
  /// if the parent node is missing. `parent[_values][segment]` is the path's value and
  /// `parent[segment]` its child node.
  ///
  /// Segments are parsed as they are visited rather than split up front, so a lookup allocates
  /// only the segments it reaches and stops at the first missing node.
  @pragma('vm:prefer-inline')
  (Map, String)? _getParent(String path) {
    if (_store.isEmpty) {
      return null;
    }

    Map node = _store;
    var start = 0;
    while (true) {
      final end = _nextStoreDelimiter(path, start);
      if (end < 0) {
        return (node, path.substring(start));
      }

      final Map? child = node[path.substring(start, end)];
      if (child == null) {
        return null;
      }
      node = child;
      start = end + delimiter.length;
    }
  }

  Map? _getNode(String path) {
    if (_getParent(path) case (final parent, final segment)) {
      return parent[segment];
    }
    return null;
  }

  (String, T)? _getNearest(
    Map? node,
    String path,
    int start,
    T? value,
  ) {
    if (node == null) {
      return null;
    }

    final end = _nextStoreDelimiter(path, start);
    final segment = path.substring(start, end < 0 ? path.length : end);

    if (end >= 0) {
      final result =
          _getNearest(node[segment], path, end + delimiter.length, value);
      if (result != null) {
        return result;
      }
    }

    final nodeValue = node[_values]?[segment];
    if (nodeValue != null && (value == null || nodeValue == value)) {
      return (end < 0 ? path : path.substring(0, end), nodeValue);
    }

    if (start > 0) {
      return null;
    }

    if (_store[_values]?[root] case T rootValue) {
      return (root, rootValue);
    }

    return null;
  }

  Map<String, T> _extractParentPath(
    Map node,
    String path,
    int start,
    Map<String, T> values,
  ) {
    while (true) {
      final end = _nextStoreDelimiter(path, start);
      final segment = path.substring(start, end < 0 ? path.length : end);
      final value = node[_values]?[segment];
      if (value != null) {
        values[end < 0 ? path : path.substring(0, end)] = value;
      }
      if (end < 0) break;
      final Map? child = node[segment];
      if (child == null) break;
      node = child;
      start = end + delimiter.length;
    }
    final rootValue = _store[_values]?[root];
    if (rootValue != null) values[ValueStore.root] = rootValue;
    return values;
  }

  Map<String, T> _extract(
    Map? node,
    Map<String, T> values,
    String path,
  ) {
    if (node == null) {
      return values;
    }

    final Map? localValues = node[_values];
    if (localValues != null) {
      localValues.forEach((key, value) {
        values[path.isEmpty ? key : '$path$delimiter$key'] = value;
      });
      if (node.length == 1) return values;
    }

    node.forEach((key, child) {
      if (key != _values) {
        _extract(child, values, path.isEmpty ? key : '$path$delimiter$key');
      }
    });

    return values;
  }

  Set<T> _extractValues(Map? node, Set<T> values) {
    if (node == null) {
      return values;
    }

    final Map<String, T>? nodeValues = node[_values];

    if (nodeValues != null) {
      values.addAll(nodeValues.values);
      if (node.length == 1) return values;
    }

    node.forEach((key, child) {
      if (key != _values) _extractValues(child, values);
    });

    return values;
  }

  T? get(String path) {
    if (_getParent(path) case (final parent, final segment)) {
      return parent[_values]?[segment];
    }
    return null;
  }

  /// Returns a map of all values that are immediate children of the given path.
  Map<String, T>? getChildValues(String path) {
    return _getNode(path)?[_values];
  }

  /// Returns the nearest path/value pair that has a value along the given path, beginning at the full path
  /// and then attempting to find a non-null value at any parent node moving up the tree.
  (String, T)? getNearest(String path) {
    return _getNearest(_store, path, 0, null);
  }

  /// Returns the nearest path that has a matching value along the given path.
  String? getNearestMatch(String path, T value) {
    return _getNearest(_store, path, 0, value)?.$1;
  }

  bool hasValue(String path) {
    return get(path) != null;
  }

  /// Returns whether the path exists in the store, either as a value or path to another descendant value.
  bool hasPath(String path) {
    if (path.isEmpty) return true;
    if (_getParent(path) case (final parent, final segment)) {
      return parent[_values]?[segment] != null || parent[segment] != null;
    }
    return false;
  }

  T write(String path, T value);
  void delete(String path, {bool recursive = true});

  /// Extracts all values under the given path into a map of flattened paths to values.
  Map<String, T> extract([String path = '']) {
    if (path.isEmpty) {
      return _extract(_store, {}, path);
    }

    final Map<String, T> values = {};

    if (_getParent(path) case (final parent, final segment)) {
      if (parent[_values]?.containsKey(segment) ?? false) {
        values[path] = parent[_values][segment];
      }

      return _extract(parent[segment], values, path);
    }

    return values;
  }

  /// Extracts all values at parent paths of the given path into a set of flat key-value pairs of paths to values.
  /// For example, if the path is users__1__friends__1 and both users__1 and users__1__friends__1
  /// exist as distinct values in the store, then it returns both values.
  Map<String, T> extractParentPath(String path) {
    return _extractParentPath(_store, path, 0, {});
  }

  /// Returns a set of the unique values that exist in the store under the given path.
  Set<T> extractValues([String path = '']) {
    if (path.isEmpty) {
      return _extractValues(_store, {});
    }

    final Set<T> values = {};

    if (_getParent(path) case (final parent, final segment)) {
      if (parent[_values]?.containsKey(segment) ?? false) {
        values.add(parent[_values][segment]);
      }

      return _extractValues(parent[segment], values);
    }

    return values;
  }

  bool get isEmpty {
    return _store.isEmpty;
  }

  /// Returns whether the store has any child values under the given path.
  bool hasChildValues(String path) {
    return getChildValues(path)?.isNotEmpty ?? false;
  }

  void clear() {
    _store = {};
  }

  Map inspect() {
    return _store;
  }

  /// While unreferenced in the codebase, toJson is implemented so that the store can be serialized
  /// using the default behavior of [jsonEncode] which is to attempt to call [toJson] on complex objects.
  Map toJson() {
    return inspect();
  }
}

lib/store/value_store.dart.source:
part of '../loon.dart';

/// A value store is a tree structure that takes a path and indexes its value into the tree as a
/// key of its parent path, enabling efficient access to all values of the parent path.
///
/// Ex. In this example, the parent path `users__2__messages` indexes the value 'Test' by its key `1`.
///
/// ```dart
/// final store = ValueStore<String>();
/// store.write('users__2__messages__1', 'Test');
/// store.write('users__2__messages__2', 'Test again');
///
/// print(store.inspect());
/// {
///   users: {
///     2: {
///       messages: {
///         __values: {
///           1: 'Test',
///           2: 'Test again',
///         }
///       }
///     }
///   }
/// }
/// ```
///
/// All values of the given path can then be retrieved as shown below:
///
/// ```dart
/// final values = store.getChildValues('users__2__messages');
///
/// print(values);
/// {
///   1: 'Test',
///   2: 'Test again',
/// }
/// ```
/// The [ValueStore] is the data structure used throughout the library for storing collections of documents.
class ValueStore<T> extends _BaseValueStore<T> {
  ValueStore([super.store]);

  static const root = _BaseValueStore.root;

  static ValueStore fromJson(Json json) {
    return ValueStore(json);
  }

  /// Merges the values and child keys of the given other node into the given node.
  Map _mergeNode(Map node, Map otherNode) {
    for (final entry in otherNode.entries) {
      final key = entry.key;

      if (key == _BaseValueStore._values) {
        if (node.containsKey(_BaseValueStore._values)) {
          node[_BaseValueStore._values] = {
            ...(node[_BaseValueStore._values] as Map),
            ...entry.value,
          };
        } else {
          node[_BaseValueStore._values] = entry.value;
        }
      } else if (node.containsKey(key)) {
        node[key] = _mergeNode(node[key], otherNode[key]);
      } else {
        node[key] = entry.value;
      }
    }

    return node;
  }

  @override
  write(String path, T value) {
    Map node = _store;
    var start = 0;
    while (true) {
      final end = _nextStoreDelimiter(path, start);
      if (end < 0) {
        break;
      }
      node = node[path.substring(start, end)] ??= {};
      start = end + _BaseValueStore.delimiter.length;
    }

    final values = node[_BaseValueStore._values] ??= <String, T>{};
    values[path.substring(start)] = value;
    return value;
  }

  /// Deletes all data under the segment of the path beginning at [start]. Returns whether
  /// the current node can be deleted as well as a result of the deleted path.
  bool _delete(
    Map node,
    String path,
    int start, [
    bool recursive = true,
  ]) {
    final end = _nextStoreDelimiter(path, start);

    if (end >= 0) {
      final segment = path.substring(start, end);
      final Map? child = node[segment];

      if (child == null) {
        return false;
      }

      if (_delete(
          child, path, end + _BaseValueStore.delimiter.length, recursive)) {
        if (node.length == 1) {
          if (start == 0) {
            node.remove(segment);
          }

          return true;
        }

        node.remove(segment);
      }
      return false;
    }

    final segment = path.substring(start);
    if (recursive) {
      node.remove(segment);
    } else {
      final Map? child = node[segment];
      if (child != null) {
        if (child.keys.length == 1 &&
            child.containsKey(_BaseValueStore._values)) {
          node.remove(segment);
        } else {
          child.remove(_BaseValueStore._values);
        }
      }
    }

    if (node.containsKey(_BaseValueStore._values)) {
      final Map values = node[_BaseValueStore._values];
      values.remove(segment);

      if (values.isEmpty) {
        node.remove(_BaseValueStore._values);
      }
    }

    return node.isEmpty;
  }

  /// Deletes the values at the given path and optionally its subtree from the store.
  @override
  delete(
    String path, {
    /// Whether the data in the subtree under the given path should also be deleted.
    /// If false, only the values at the given path are deleted and the subtree is maintained.
    bool recursive = true,
  }) {
    if (path.isEmpty) {
      _store = {};
      return;
    }

    if (_store.isEmpty) return;

    _delete(_store, path, 0, recursive);
  }

  /// Grafts the data under the given path from the other store into this store. Returns
  /// whether the other store's node can be deleted after grafted.
  bool _graft(Map node, Map? otherNode, String path, int start) {
    if (otherNode == null) {
      return false;
    }

    final end = _nextStoreDelimiter(path, start);
    final segment = path.substring(start, end < 0 ? path.length : end);

    if (end >= 0) {
      final Map? otherChildNode = otherNode[segment];

      if (otherChildNode == null) {
        return false;
      }

      final Map childNode = node[segment] ??= {};

      if (_graft(childNode, otherChildNode, path,
          end + _BaseValueStore.delimiter.length)) {
        if (otherNode.length == 1) {
          if (start == 0) {
            otherNode.remove(segment);
          }
          return true;
        }
      }

      return false;
    }

    if (otherNode.containsKey(_BaseValueStore._values)) {
      final otherValues = otherNode[_BaseValueStore._values];

      if (otherValues.containsKey(segment)) {
        final value = otherValues.remove(segment);

        final values = node[_BaseValueStore._values] ??= {};
        values[segment] = value;
      }

      if (otherNode[_BaseValueStore._values].isEmpty) {
        otherNode.remove(_BaseValueStore._values);
      }
    }

    final Map? otherChildNode = otherNode[segment];
    if (otherChildNode == null) {
      return otherNode.isEmpty;
    }

    otherNode.remove(segment);

    final Map childNode = node[segment] ??= {};

    _mergeNode(childNode, otherChildNode);

    return otherNode.isEmpty;
  }

  /// Removes the subtree at the given [path] of the other provided [ValueStore] and recursively
  /// merges it onto this store at the given path.
  void graft(
    ValueStore<T> other, [
    String? path = '',
  ]) {
    if (path == null || path.isEmpty) {
      final otherNode = other._store;
      other.clear();
      _mergeNode(_store, otherNode);
    } else {
      _graft(_store, other._store, path, 0);
    }
  }
}

